/**
 * Node input (T-007 R8, T-008 R6/D-28) — DOM glue that turns a double-click
 * on the canvas into a `node.create` dispatch. All coordinate conversion goes
 * through `view/camera` (I-02) and the shared position helper
 * `pointerToCanvasPos`; every document mutation goes through
 * `docStore.dispatch` (I-03). IDs are generated by the caller-supplied
 * `newId` (D-11) — main.ts passes `crypto.randomUUID()`.
 *
 * D-28: a double-click on **empty space** creates a card and selects it; a
 * double-click on an existing node creates nothing (reserved for text
 * editing later). The "may I create here?" decision itself is pure
 * (`shouldCreateCardAt` in cardCommand.ts, unit-tested there).
 */

import type { Point } from '../core/geometry';
import type { DocStore } from '../core/store';
import { screenToWorld } from '../view/camera';
import type { CameraStore } from '../view/cameraStore';
import type { UiStore } from '../view/uiStore';
import { createCardAt, shouldCreateCardAt } from './cardCommand';
import { pointerToCanvasPos } from './cursor';

export interface NodeInputOptions {
  canvas: HTMLCanvasElement;
  cameraStore: CameraStore;
  docStore: DocStore;
  /** The UI store: the new card is selected after creation (D-28). */
  uiStore: UiStore;
  /** Generates fresh ids (D-11), e.g. `() => crypto.randomUUID()`. */
  newId: () => string;
}

export interface NodeInput {
  detach(): void;
}

/**
 * Attach node-creation input: on `dblclick` on the canvas (primary button,
 * not touch), convert the click to a world point through the current camera
 * and dispatch a card-creation command centred there — but only when the
 * point is empty space (D-28). The created card is selected. Returns a
 * `detach()` that removes every listener.
 */
export function attachNodeInput(opts: NodeInputOptions): NodeInput {
  const { canvas, cameraStore, docStore, uiStore, newId } = opts;

  // Some browsers synthesise a dblclick from a touch double-tap; remember
  // the pointer type of the last pointerdown so those can be ignored (R8).
  let lastPointerWasTouch = false;

  function onPointerDown(e: PointerEvent): void {
    lastPointerWasTouch = e.pointerType === 'touch';
  }

  function onDblClick(e: MouseEvent): void {
    if (e.button !== 0) return; // primary button only
    if (lastPointerWasTouch) return; // never touch
    const canvasPos: Point = pointerToCanvasPos(canvas, e.clientX, e.clientY);
    const world = screenToWorld(cameraStore.get(), canvasPos);
    // D-28: double-click on an existing node creates nothing.
    if (!shouldCreateCardAt(docStore.get(), world)) return;
    const id = newId();
    docStore.dispatch(createCardAt(world, id));
    // D-28: the new card is selected.
    uiStore.setSelection([id]);
  }

  canvas.addEventListener('pointerdown', onPointerDown);
  canvas.addEventListener('dblclick', onDblClick);

  return {
    detach() {
      canvas.removeEventListener('pointerdown', onPointerDown);
      canvas.removeEventListener('dblclick', onDblClick);
    },
  };
}
